CREATE TABLE public.marketplace_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL UNIQUE REFERENCES public.job_applications(id) ON DELETE CASCADE, buyer_id uuid NOT NULL REFERENCES public.profiles(id), seller_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.marketplace_conversations TO authenticated; GRANT ALL ON public.marketplace_conversations TO service_role;
ALTER TABLE public.marketplace_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON public.marketplace_conversations FOR SELECT TO authenticated USING(auth.uid() IN(buyer_id,seller_id) AND public.account_is_active() AND public.website_available());
CREATE FUNCTION public.conversation_participant(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_is_active() AND public.website_available() AND EXISTS(SELECT 1 FROM public.marketplace_conversations WHERE id=cid AND auth.uid() IN(buyer_id,seller_id)) $$;
REVOKE ALL ON FUNCTION public.conversation_participant(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.conversation_participant(uuid) TO authenticated;
CREATE TABLE public.marketplace_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.marketplace_conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id), request_id uuid NOT NULL, body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 4000), attachment_path text, attachment_name text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(sender_id,request_id));
GRANT SELECT ON public.marketplace_messages TO authenticated; GRANT ALL ON public.marketplace_messages TO service_role;
ALTER TABLE public.marketplace_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON public.marketplace_messages FOR SELECT TO authenticated USING(public.conversation_participant(conversation_id));
CREATE TABLE public.marketplace_reads (conversation_id uuid REFERENCES public.marketplace_conversations(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(conversation_id,user_id));
GRANT SELECT ON public.marketplace_reads TO authenticated; GRANT ALL ON public.marketplace_reads TO service_role;
ALTER TABLE public.marketplace_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_read ON public.marketplace_reads FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.conversation_participant(conversation_id));
CREATE TABLE public.marketplace_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL UNIQUE REFERENCES public.marketplace_conversations(id) ON DELETE CASCADE, buyer_id uuid NOT NULL REFERENCES public.profiles(id), seller_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL, terms text NOT NULL CHECK(char_length(terms) BETWEEN 20 AND 8000), amount numeric NOT NULL CHECK(amount>0 AND amount<=100000000), currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), status text NOT NULL DEFAULT 'offered' CHECK(status IN('offered','accepted_unfunded','declined','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz);
GRANT SELECT ON public.marketplace_contracts TO authenticated; GRANT ALL ON public.marketplace_contracts TO service_role;
ALTER TABLE public.marketplace_contracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON public.marketplace_contracts FOR SELECT TO authenticated USING(public.conversation_participant(conversation_id));
CREATE TABLE public.marketplace_milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.marketplace_contracts(id) ON DELETE CASCADE, title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 150), amount numeric NOT NULL CHECK(amount>0), due_date date, position integer NOT NULL);
GRANT SELECT ON public.marketplace_milestones TO authenticated; GRANT ALL ON public.marketplace_milestones TO service_role;
ALTER TABLE public.marketplace_milestones ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON public.marketplace_milestones FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.marketplace_contracts c WHERE c.id=contract_id AND public.conversation_participant(c.conversation_id)));
CREATE TABLE public.marketplace_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, conversation_id uuid NOT NULL REFERENCES public.marketplace_conversations(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN('message','offer','accepted','declined','cancelled')), read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.marketplace_notifications TO authenticated; GRANT ALL ON public.marketplace_notifications TO service_role;
ALTER TABLE public.marketplace_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_read ON public.marketplace_notifications FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.conversation_participant(conversation_id));
CREATE INDEX marketplace_message_time ON public.marketplace_messages(conversation_id,created_at);
CREATE INDEX marketplace_notification_owner ON public.marketplace_notifications(user_id,created_at);
ALTER PUBLICATION supabase_realtime ADD TABLE public.marketplace_messages,public.marketplace_conversations,public.marketplace_contracts,public.marketplace_notifications;